INSERT INTO deep_dive_stat_translations (stat_id, lang, stat_value, stat_label) VALUES ((SELECT MAX(id) FROM deep_dive_stats), 'en', '2030', 'SAF-T reaches every VAT-registered entity (Phase 5)');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 0 FROM countries WHERE code = 'BG';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'B2G format & platform', '[["Format", "EN 16931-compliant structured e-invoice"], ["Platform", "Centralized Automated Information System for Electronic Public Procurement (CAIS EPP)"], ["Legal basis", "Article 115a, Public Procurement Act (State Gazette 86/18)"], ["Scope", "Contracts above EU public procurement thresholds, central and sub-central government alike"]]', 'A paper or plain PDF invoice does not satisfy this requirement — Bulgarian contracting authorities must be able to receive and process a genuinely structured e-invoice through CAIS EPP.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 1 FROM countries WHERE code = 'BG';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'SAF-T reporting format (separate from invoicing)', '[["Format", "XML, aligned with the OECD SAF-T standard"], ["Monthly filing", "General ledger, accounts payable/receivable, purchase and sales invoice data — due 14th of the following month"], ["Annual filing", "Fixed-asset data, due with the corporate income tax return"], ["On-demand", "Inventory movement data, on NRA request"]]', 'SAF-T is a periodic bookkeeping-data export, not an invoice-issuance requirement — it does not change how you issue, send, or receive an invoice, only what accounting data you periodically report to the NRA.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 0 FROM countries WHERE code = 'BG';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'SAF-T phased rollout by size', '[["Phase 1 — 1 Jan 2026", "Large enterprises: 2023 revenue > BGN 300m, or tax/social payments > BGN 3.5m"], ["Phase 2 — 1 Jan 2027", "Same thresholds, 2024 data — medium/small entities crossing them join"], ["Phase 3 — 1 Jan 2028", "Threshold drops sharply: 2025 revenue > BGN 15m, or payments > BGN 1.5m"], ["Phase 4 — 1 Jan 2029", "All enterprises classified large, medium or small"], ["Phase 5 — 1 Jan 2030", "Every remaining VAT-registered entity, including micro-enterprises"]]', 'Each phase carries a documented six-month grace period allowing corrections to initial monthly filings without penalty, through the seventh month''s deadline.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 1 FROM countries WHERE code = 'BG';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', 'B2B: fully voluntary', '[["Clearance authority", "None"], ["Mandated channel", "None"], ["Legal basis for voluntary use", "Bulgarian VAT Act, aligned with EU Directive 2014/55/EU"]]', 'A Bulgarian business may exchange structured e-invoices with a trading partner today, entirely by mutual agreement — there is no domestic legal requirement pushing it, and no penalty for not doing so.', NULL);
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 0 FROM countries WHERE code = 'BG';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '⚖️ No B2B e-invoicing fine exists — because no B2B mandate exists', NULL, NULL, 'There is nothing to penalize on the invoicing side: Bulgaria has never legislated a B2B e-invoicing or clearance requirement, so no fine schedule attaches to how you issue or exchange invoices with another business.');
INSERT INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 1 FROM countries WHERE code = 'BG';
INSERT INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) VALUES ((SELECT MAX(id) FROM deep_dive_cards), 'en', '📋 SAF-T penalties are a separate tax-procedure matter', NULL, NULL, 'Failing to file, or filing late, is reported by a single specialist compliance source as carrying a BGN 5,000–15,000 fine for a first violation and BGN 10,000–30,000 for a repeat — treat these figures as plausible, not confirmed, until cross-checked against the NRA''s own published guidance.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 0 FROM countries WHERE code = 'BG';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Confirm your B2G invoicing already runs through CAIS EPP', 'If you supply Bulgarian public bodies, verify your invoices are structured EN 16931 e-invoices submitted via CAIS EPP — this obligation has applied since November 2019.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 1 FROM countries WHERE code = 'BG';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Work out which SAF-T phase applies to you', 'Check your annual revenue and tax/social-security payments against the phase thresholds above to find your first mandatory filing date, from 2026 through 2030.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 2 FROM countries WHERE code = 'BG';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Get SAF-T-capable accounting software in place', 'Confirm your accounting or ERP system can produce the required monthly general ledger, AP/AR and invoice-data XML export well before your phase''s first deadline — the six-month grace period is for corrections, not for starting from zero.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 3 FROM countries WHERE code = 'BG';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Don''t confuse SAF-T with an e-invoicing mandate', 'SAF-T changes what accounting data you report and when — it does not require you to change how you issue or exchange invoices with other businesses, since no such mandate exists in Bulgaria today.');
INSERT INTO deep_dive_steps (country_id, sort_order) SELECT id, 4 FROM countries WHERE code = 'BG';
INSERT INTO deep_dive_step_translations (step_id, lang, title, description) VALUES ((SELECT MAX(id) FROM deep_dive_steps), 'en', 'Watch for a domestic B2B mandate announcement', 'Bulgaria has made no domestic B2B e-invoicing announcement as of this research round, but the 1 July 2030 EU ViDA floor applies regardless — monitor for a domestic mandate that would likely arrive earlier.');
